export const config={id:'orbit-observatory',title:'轨道观测台',subtitle:'ORBITAL CHOREOGRAPHY',description:'五条倾斜轨道围绕一枚光核缓慢交错，轨道展开度直接改变空间构型。',category:'coding-motion',useCase:'科学主题视觉、音乐舞台背景、交互展陈',accent:'#b8eccf',duration:24,parameter:{label:'轨道展开',min:0,max:100,step:1,value:65,unit:'%'}};
const TAU=Math.PI*2;
export function orbitalState(t,value){const spread=Math.max(0,Math.min(100,value))/100;return {spread,rings:Array.from({length:5},(_,i)=>{const rx=125+i*(29+spread*18),ry=rx*(.25+spread*.12),rotation=-.68+i*.28;const phase=t*TAU/config.duration*(1+i%2)*(i%2?-1:1)+i*1.4;return {rx,ry,rotation,phase,x:Math.cos(phase)*rx,y:Math.sin(phase)*ry};})};}
function text(c,s,x,y,size=12,color='#a5b6be'){c.fillStyle=color;c.font=`${size}px "Noto Sans CJK SC", ui-monospace, monospace`;c.fillText(s,x,y);}
export function render(c,{t,value,width,height}){c.save();c.scale(width/1200,height/800);c.fillStyle='#08141d';c.fillRect(0,0,1200,800);
const g=c.createRadialGradient(600,400,20,600,400,490);g.addColorStop(0,'#183b40');g.addColorStop(1,'#08141d');c.fillStyle=g;c.fillRect(0,0,1200,800);
c.strokeStyle='#ffffff0c';c.lineWidth=1;for(let x=48;x<1200;x+=48){c.beginPath();c.moveTo(x,145);c.lineTo(x,690);c.stroke();}for(let y=162;y<700;y+=48){c.beginPath();c.moveTo(48,y);c.lineTo(1152,y);c.stroke();}
text(c,'STUDIO / CELESTIAL MECHANISMS',48,52,13,'#b8eccf');text(c,'轨道观测台',48,97,32,'#f1f2db');text(c,'01 — ORBITAL CHOREOGRAPHY',852,55,12);text(c,'ABSTRACT • NOT EPHEMERIS',852,78,12);
c.save();c.translate(600,420);c.strokeStyle='#9fe4bd30';c.beginPath();c.arc(0,0,304,0,TAU);c.stroke();for(let i=0;i<72;i++){const a=i/72*TAU;c.strokeStyle=i%6===0?'#9fe4bd88':'#9fe4bd30';c.beginPath();c.moveTo(Math.cos(a)*313,Math.sin(a)*313);c.lineTo(Math.cos(a)*(i%6===0?323:317),Math.sin(a)*(i%6===0?323:317));c.stroke();}
const state=orbitalState(t,value);for(const [i,r] of state.rings.entries()){c.save();c.rotate(r.rotation);c.strokeStyle=['#d7e7aa55','#82d3bd66','#e3bca655','#c4d9e655','#96b7ba66'][i];c.lineWidth=1.3;c.beginPath();c.ellipse(0,0,r.rx,r.ry,0,0,TAU);c.stroke();c.lineWidth=3;c.strokeStyle=['#e3e8ab','#87dfc1','#e7bc9c','#d7ecf0','#8fbcbe'][i];c.beginPath();c.ellipse(0,0,r.rx,r.ry,0,r.phase-.36,r.phase);c.stroke();c.shadowColor=c.strokeStyle;c.shadowBlur=18;c.fillStyle=c.strokeStyle;c.beginPath();c.arc(r.x,r.y,i===2?8:5,0,TAU);c.fill();c.shadowBlur=0;c.restore();}
const glow=c.createRadialGradient(0,0,1,0,0,80);glow.addColorStop(0,'#eaffd955');glow.addColorStop(1,'#eaffd900');c.fillStyle=glow;c.fillRect(-80,-80,160,160);c.fillStyle='#eaf4cb';c.beginPath();c.arc(0,0,15,0,TAU);c.fill();c.strokeStyle='#eaf4cb66';c.beginPath();c.arc(0,0,24,0,TAU);c.stroke();c.restore();
text(c,'FIVE PATHS',48,365,13,'#eaf4cb');text(c,'ONE QUIET CENTER',48,387);text(c,'Independent phases',48,419);text(c,'Shared composition',48,440);text(c,'展开 / SPREAD',991,390,12);text(c,`${Math.round(value)}%`,991,428,30,'#b8eccf');
c.strokeStyle='#93b3b333';c.beginPath();c.moveTo(48,741);c.lineTo(1152,741);c.stroke();text(c,'Move the slider to open the orbital arrangement.',48,773,13);text(c,'GENERATIVE STUDY / 01',956,773,12);c.restore();}
